/// <summary>
/// PricingAttribute of table <c>InventTable</c> field TaxRateType.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(InventTable, TaxRateType))]
internal class GUPPricingAttributeInventTableTaxRateType extends GUPPricingAttributeInventTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, TaxRateType);
}

public str getRefValue(Str _defaultValue)
{
    TaxRateType taxRateType;
    str ret = "";
    boolean isFirstAttributeToAppend = true;
    Query query = new Query();
    query.addDataSource(tableNum(TaxRateType)).addRange(fieldNum(TaxRateType, RecId)).value(_defaultValue);
    QueryRun qr = new QueryRun(query);
    while (qr.next())
    {
        taxRateType = qr.get(tableNum(TaxRateType), 1);
        if (!isFirstAttributeToAppend)
        {
            ret += ",";
        }
        else
        {
            isFirstAttributeToAppend = false;
        }
        ret += taxRateType.name;
    }

    return ret;
}

public boolean validate(Str _defaultValue)
{
    var recId = str2Int64(_defaultValue);
    return TaxRateType::find(recId) ? true : false;
}

public void lookupAllowedValues(object _formStringControl)
{
    GUPTaxRateTypeLookup taxRateTypeLookup = new GUPTaxRateTypeLookup(true);
    taxRateTypeLookup.parmreturnRefRecID(true);
    taxRateTypeLookup.performLookup(_formStringControl);

}
